package net.civeira.phylax.features.access.userinvitation.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.user.domain.UserReference;

class AcceptedByVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property accepted by of user invitation ")
  void test_accepted_by_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10", AcceptedByVO.fromReference("10").getAcceptedByUid().orElse(null),
        "The builder must store the reference value");
    Assertions.assertEquals("11",
        AcceptedByVO.tryFromReference("11").getAcceptedByUid().orElse(null),
        "The builder must store the reference value");
    Assertions.assertEquals("12",
        AcceptedByVO.tryFromReference("12", fails).getAcceptedByUid().orElse(null),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertFalse(AcceptedByVO.nullValue().getAcceptedBy().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(AcceptedByVO.tryFrom(null).getAcceptedBy().isPresent(),
        "With a null value, no present result");
    Assertions.assertFalse(AcceptedByVO.fromReference(null).getAcceptedBy().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(UserReference.of("one"),
        AcceptedByVO.from(UserReference.of("one")).getAcceptedBy().orElse(null));
    Assertions.assertThrows(ConstraintException.class, () -> AcceptedByVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + UserReference.of("one") + "]",
        AcceptedByVO.from(UserReference.of("one")).toString());
  }
}
